query ReviewThreads($owner: String!, $repo: String!, $number: Int!) {
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) {
      reviewThreads(first: 20) {
        nodes {
          id
          isResolved
          isOutdated
          path
          comments(first: 8) {
            nodes { author { login } body }
          }
        }
      }
    }
  }
}
